insert into dining_tap select no_plan();
 insert into auth.users(id,email) values(employee,'table-qa-'||employee||'@example.test');
 insert into public.user_profiles(id,display_name) values(employee,'Table QA') on conflict(id) do nothing;
 insert into public.shops(id,name,created_by) values(s,'Dining QA',a),(other_s,'Other dining QA',a);
 insert into public.shop_members(shop_id,user_id,role,granted_by) values(s,a,'OWNER',a),(s,employee,'STAFF',a);
 insert into public.shop_locations(shop_id,latitude,longitude) values(s,16,103);
 insert into public.categories(id,shop_id,name) values(cat,s,'QA');
 insert into public.products(id,shop_id,category_id,name,base_price_satang) values(p,s,cat,'Kebab',3900);
 insert into dining_context select a,employee,s,other_s,t,b,qr_token,p,gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),null,gen_random_uuid(),null,ss from public.dining_tables where id=t;
insert into dining_tap select ok(not has_table_privilege('anon','public.table_bills','SELECT'),'public cannot read bills directly');
insert into dining_tap select ok(not has_function_privilege('anon','public.pay_table_bill(uuid,public.payment_method,integer,uuid,text)','EXECUTE'),'public cannot record table payments');
insert into dining_tap select ok(not has_function_privilege('authenticated','public.create_table_qr_order(uuid,uuid,uuid,uuid,uuid,uuid,double precision,double precision,double precision,timestamptz,jsonb,text)','EXECUTE'),'QR checkout restricted to Edge service role');
insert into dining_tap select is(public.get_dining_table_context((select qr from dining_context))->>'tableName','Table 5','QR resolves public table identity');
insert into dining_tap select throws_ok($$select public.archive_dining_table(shop,tid) from dining_context$$,'P0001','Close the active table round before deleting this table.','owner cannot archive a table with an active round');
insert into dining_tap select throws_ok($$select public.list_dining_tables((select other_shop from dining_context))$$,'42501','Active shop membership is required.','cross shop isolated');
insert into dining_tap select throws_ok($$select public.open_dining_table((select tid from dining_context))$$,'23505',null,'cannot open a table twice');
insert into dining_tap select is(public.track_table_round(gen_random_uuid()),null::jsonb,'unknown token reveals no round');
insert into dining_tap select is(public.create_table_qr_order((select shop from dining_context),(select qr from dining_context),(select bill from dining_context),(select guest_a from dining_context),(select key_a from dining_context),(select token_a from dining_context),16,103,10,now(),jsonb_build_array(jsonb_build_object('productId',(select product from dining_context),'quantity',1)))->>'orderId',(select order_a::text from dining_context),'same request retries one order');
insert into dining_tap select lives_ok($$select public.create_table_qr_order(shop,qr,bill,guest_b,gen_random_uuid(),gen_random_uuid(),16,103,10,now(),jsonb_build_array(jsonb_build_object('productId',product,'quantity',2))) from dining_context$$,'another guest adds another round');
insert into dining_tap select lives_ok($$select public.create_table_pos_order(shop,bill,gen_random_uuid(),jsonb_build_array(jsonb_build_object('productId',product,'quantity',1))) from dining_context$$,'staff adds food to same table');
insert into dining_tap select is(public.get_table_bill((select bill from dining_context))->>'totalSatang','15600','all rounds aggregate server prices');
insert into dining_tap select is(jsonb_array_length(public.track_table_round((select guest_a from dining_context))->'orders'),1,'guest A sees only own order');
insert into dining_tap select is(jsonb_array_length(public.track_table_round((select guest_b from dining_context))->'orders'),1,'guest B sees only own order');
insert into dining_tap select is(public.track_table_round((select guest_a from dining_context))->>'ownTotalSatang','3900','guest total is private own total');
insert into dining_tap select is(public.list_active_staff_orders((select shop from dining_context))->'orders'->0->>'tableName','Table 5','kitchen queue includes table label');
insert into dining_tap select throws_ok($$select public.record_order_payment((select order_a from dining_context),'BANK_TRANSFER',3900)$$,'P0001','Collect payment from the table bill.','individual collection blocked');
insert into dining_tap select lives_ok($$select public.set_table_bill_checkout((select bill from dining_context),true)$$,'staff freezes table bill');
insert into dining_tap select throws_ok($$select public.create_table_pos_order(shop,bill,gen_random_uuid(),'[]'::jsonb) from dining_context$$,'P0001','Table is not accepting orders.','POS rejects new orders when checking out');
insert into dining_tap select throws_ok($$select public.create_table_qr_order(shop,qr,bill,guest_a,gen_random_uuid(),gen_random_uuid(),16,103,10,now(),jsonb_build_array(jsonb_build_object('productId',product,'quantity',1))) from dining_context$$,'P0001','Table is not accepting orders.','QR rejects new rounds when checking out');
insert into dining_tap select throws_ok($$select public.cancel_customer_order((select token_a from dining_context))$$,'P0001','Reopen the bill before cancellation.','cancellation cannot race frozen bill');
insert into dining_tap select throws_ok($$select public.pay_table_bill(bill,'BANK_TRANSFER',15600,payment_key,'stale') from dining_context$$,'40001','Bill changed. Review before payment.','stale bill review rejected');
insert into dining_tap select lives_ok($$select public.pay_table_bill(bill,'BANK_TRANSFER',15600,payment_key,fp) from dining_context$$,'staff records combined payment atomically');
insert into dining_tap select lives_ok($$select public.pay_table_bill(bill,'BANK_TRANSFER',15600,payment_key,fp) from dining_context$$,'exact payment retry is idempotent');
insert into dining_tap select is((select count(*)::integer from public.table_bill_payments where bill_id=(select bill from dining_context)),1,'one table payment receipt');
insert into dining_tap select is((select count(*)::integer from public.payments where shop_id=(select shop from dining_context)),3,'three ledger allocations without duplicates');
insert into dining_tap select is((select sum(paid_amount_satang)::bigint from public.payments where shop_id=(select shop from dining_context)),15600::bigint,'collected ledger equals bill total');
insert into dining_tap select is(public.track_table_round((select guest_a from dining_context))->>'status','PAID','old customer link shows settled round');
insert into dining_tap select throws_ok($$select public.close_dining_table((select bill from dining_context))$$,'P0001','Finish pending food before closing the table.','paid table with pending food cannot close');
insert into dining_tap select lives_ok($$select public.close_dining_table((select bill from dining_context))$$,'staff closes settled table');
insert into dining_tap select is(public.track_table_round((select guest_a from dining_context))->>'closed','true','old round remains finished');
insert into dining_tap select lives_ok($$select public.open_dining_table((select tid from dining_context))$$,'table reused for new diners');
insert into dining_tap select isnt(public.get_dining_table_context((select qr from dining_context))->>'billId',(select bill::text from dining_context),'static QR resolves new round');
insert into dining_tap select is(public.track_table_round((select guest_a from dining_context))->>'billId',(select bill::text from dining_context),'old token never rebinds to new bill');
insert into dining_tap select throws_ok($$select public.close_store_session((select shop from dining_context),(select store_id from dining_context))$$,'P0001','Close active dining tables before closing the store.','empty active table also blocks closing shop');
insert into dining_tap select lives_ok($$select public.create_pos_order(shop,gen_random_uuid(),jsonb_build_array(jsonb_build_object('productId',product,'quantity',1))) from dining_context$$,'original takeaway POS unchanged');
insert into dining_tap select is(public.get_sales_dashboard((select shop from dining_context),current_date,current_date)->>'netCollectedSalesSatang','15600','sales reports count table revenue only once');
insert into dining_tap select throws_ok($$select public.cancel_table_guest_order(guest_b,order_a) from dining_context$$,'P0002','Order not found.','another guest cannot cancel this order');
insert into dining_tap select lives_ok($$select public.cancel_table_guest_order(guest_a,order_a) from dining_context$$,'guest cancels own queued order');
insert into dining_tap select lives_ok($$select public.cancel_table_guest_order(guest_a,order_a) from dining_context$$,'cancellation retry is idempotent');
insert into dining_tap select is(public.get_table_bill((select bill from dining_context))->>'totalSatang','0','cancelled orders excluded from combined bill');
insert into dining_tap select lives_ok($$select public.close_dining_table(bill) from dining_context$$,'all cancelled table closes without payment');
insert into dining_tap select throws_ok($$select public.cancel_table_guest_order(guest_a,order_a) from dining_context$$,'P0001','Preparation has started. Please contact the shop.','preparing food cannot be cancelled by guest');
insert into dining_tap select lives_ok($$select public.pay_table_bill(bill,'CASH',10000,payment_key,fp) from dining_context$$,'cash combined payment accepts larger tender');
insert into dining_tap select is((select change_satang from public.table_bill_payments where bill_id=(select bill from dining_context)),6100,'cash change recorded once');
insert into dining_tap select is(public.get_table_bill((select bill from dining_context))->>'closed','true','completed food and settled bill automatically close table');
insert into dining_tap select throws_ok($$select public.pay_table_bill(bill,'CASH',10000,gen_random_uuid(),fp) from dining_context$$,'P0001','Bill is already paid.','different payment request cannot charge again');
insert into dining_tap select throws_ok($$select public.archive_dining_table(shop,tid) from dining_context$$,'42501','Owner access required.','staff cannot archive tables');
insert into dining_tap select lives_ok($$select public.archive_dining_table(shop,tid) from dining_context$$,'owner archives a closed table');
insert into dining_tap select is(public.list_dining_tables((select shop from dining_context)),'[]'::jsonb,'archived table is hidden');
insert into dining_tap select is(public.get_dining_table_context((select qr from dining_context)),null::jsonb,'archived QR no longer resolves');
insert into dining_tap select is(public.get_table_bill((select bill from dining_context))->>'status','PAID','archived table retains its paid bill');
insert into dining_tap select lives_ok($$select public.save_dining_table(shop,'Table 5') from dining_context$$,'archived table name can be reused');
insert into dining_tap select * from finish();
