begin;
create extension if not exists pgtap with schema extensions;
create temporary table dining_tap(result text) on commit drop;
create temporary table dining_context(owner_id uuid,staff_id uuid,shop uuid,other_shop uuid,tid uuid,bill uuid,qr uuid,product uuid,guest_a uuid,guest_b uuid,key_a uuid,token_a uuid,order_a uuid,payment_key uuid,fp text,store_id uuid);
do $$
declare a uuid; employee uuid:=gen_random_uuid(); s uuid:=gen_random_uuid(); other_s uuid:=gen_random_uuid(); cat uuid:=gen_random_uuid(); p uuid:=gen_random_uuid(); t uuid; b uuid; ss uuid;
begin
 select user_id into strict a from public.shop_members where role='OWNER' and status='ACTIVE' limit 1;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 t:=public.save_dining_table(s,'Table 5');
 ss:=(public.open_store_session(s)->>'id')::uuid;
 b:=public.open_dining_table(t);
end $$;
update dining_context set order_a=(public.create_table_qr_order(shop,qr,bill,guest_a,key_a,token_a,16,103,10,now(),jsonb_build_array(jsonb_build_object('productId',product,'quantity',1)))->>'orderId')::uuid;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select staff_id from dining_context),'role','authenticated')::text,true);
update dining_context set fp=public.get_table_bill(bill)->>'fingerprint';
select public.update_order_status(id,status,'COMPLETED') from public.orders where table_bill_id=(select bill from dining_context);
select public.close_dining_table((public.get_dining_table_context((select qr from dining_context))->>'billId')::uuid);
select set_config('request.jwt.claims',jsonb_build_object('sub',(select owner_id from dining_context),'role','authenticated')::text,true);
update dining_context set bill=public.open_dining_table(tid),key_a=gen_random_uuid(),token_a=gen_random_uuid();
update dining_context set guest_a=gen_random_uuid(),guest_b=gen_random_uuid();
update dining_context set order_a=(public.create_table_qr_order(shop,qr,bill,guest_a,key_a,token_a,16,103,10,now(),jsonb_build_array(jsonb_build_object('productId',product,'quantity',1)))->>'orderId')::uuid;
update dining_context set bill=public.open_dining_table(tid),key_a=gen_random_uuid(),token_a=gen_random_uuid(),guest_a=gen_random_uuid();
update dining_context set order_a=(public.create_table_qr_order(shop,qr,bill,guest_a,key_a,token_a,16,103,10,now(),jsonb_build_array(jsonb_build_object('productId',product,'quantity',1)))->>'orderId')::uuid;
select public.update_order_status(order_a,'QUEUED','PREPARING') from dining_context;
select public.update_order_status(order_a,'PREPARING','COMPLETED') from dining_context;
select public.set_table_bill_checkout(bill,true) from dining_context;
update dining_context set fp=public.get_table_bill(bill)->>'fingerprint',payment_key=gen_random_uuid();
select set_config('request.jwt.claims',jsonb_build_object('sub',(select staff_id from dining_context),'role','authenticated')::text,true);
select set_config('request.jwt.claims',jsonb_build_object('sub',(select owner_id from dining_context),'role','authenticated')::text,true);
select result from dining_tap;
rollback;
